// Force TM — textos em português, inglês e espanhol
import Foundation

let supportedLangs = ["pt", "en", "es"]
func resolveLang() -> String {
    let pref = UserDefaults.standard.string(forKey: "lang") ?? "auto"
    if supportedLangs.contains(pref) { return pref }
    for l in Locale.preferredLanguages {
        let c = String(l.prefix(2))
        if supportedLangs.contains(c) { return c }
    }
    return "en"
}
var currentLang = resolveLang()
func appLocale() -> Locale {
    Locale(identifier: currentLang == "pt" ? "pt_BR" : currentLang == "es" ? "es_ES" : "en_US")
}
func L(_ k: String) -> String { S[k]?[currentLang] ?? S[k]?["en"] ?? k }
func Lf(_ k: String, _ args: CVarArg...) -> String { String(format: L(k), locale: appLocale(), arguments: args) }

